/* return an unused cookie */
uint64_t getrandomcookie(GHashTable * phash)
{
	uint64_t cookie = 0;
	int i;
	do {
		/* RAND_MAX may be as low as 2^15 */
		for (i = 1; i <= 5; i++)
			cookie ^= random() ^ (cookie << 15);
	} while (g_hash_table_lookup(phash, &cookie));
	return cookie;
}

