```c
/* number of base-TREEDIRSIZE digits needed to address all blocks of a
 * file of size bytes; one digit names the block file itself, any
 * further digits name directories */
static int treelevels(off_t size) {
	int levels = 1;
	uint64_t capacity = TREEDIRSIZE; /* blocks addressable */

	while (capacity < (uint64_t)((size + TREEPAGESIZE - 1) / TREEPAGESIZE)) {
		capacity *= TREEDIRSIZE;
		levels++;
	}
	return levels;
}
```

