```c
/**
 * Read up to len bytes at offset a from a treefiles export, where
 * the data is stored in a tree of small block files. Bytes that were
 * never written read back as zeroes.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error.
 **/
ssize_t rawexptreefile_read(off_t a, char *buf, size_t len, CLIENT *client) {
	off_t foffset;
	ssize_t retval;
	int fhandle;

	/* reads never cross block boundaries */
	if (len > (size_t)(TREEPAGESIZE - a % TREEPAGESIZE))
		len = TREEPAGESIZE - a % TREEPAGESIZE;

	fhandle = open_treefile(client->exportname, O_RDONLY, client->exportsize, a, &client->lock);
	if (fhandle < 0) {
		if (errno == ENOENT) {
			/* block was never written; it reads back as zeroes */
			memset(buf, 0, len);
			return len;
		}
		return -1;
	}
	foffset = a % TREEPAGESIZE;
	retval = pread(fhandle, buf, len, foffset);
	if (retval >= 0 && (size_t)retval < len) {
		/* short file: treat missing bytes as zeroes */
		memset(buf + retval, 0, len - retval);
		retval = len;
	}
	close(fhandle);
	return retval;
}
```

