arguments.content:
/*
 * Tree files support
 *
 * A treefiles export stores its data in a tree of small fixed-size block
 * files below the directory named by the exportname, rather than in a
 * single (potentially very large) file. This is useful to provide a
 * virtual block device on an underlying filesystem that does not handle
 * large files well, for example fuse/ftpfs, davfs or other network
 * filesystems.
 *
 * The individual block files are TREEPAGESIZE bytes each, and every
 * directory holds at most TREEDIRSIZE files or subdirectories. The
 * nesting level of subdirectories required to address all blocks of the
 * export is derived from the export size. Subdirectories are named
 * TREEXXXX, block files FILEXXXX, where XXXX is the zero-padded index
 * of the entry within its parent directory.
 */

#include <nbdsrv.h>

#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>

#include <sys/stat.h>
#include <sys/types.h>

#include "treefiles.h"
#include "nbd-debug.h"

/* Extra space needed on top of the length of the exportname to store a
 * full block file path: with 64 bit file offsets, an export can span at
 * most 6 levels of TREEDIRSIZE entries ("/TREEXXXX" each, plus the
 * "FILEXXXX" leaf and the trailing NUL). */
#define TREEPATH_EXTRA 64

/**
 * Compute the number of digits needed to address all blocks of an export
 * of the given size in base TREEDIRSIZE. One of the digits is used for
 * the block file name itself, the remaining ones for subdirectories.
 **/
static int treelevels(off_t size) {
	uint64_t blocks = ((uint64_t)size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	uint64_t capacity = TREEDIRSIZE;
	int levels = 1;

	while (capacity < blocks) {
		capacity *= TREEDIRSIZE;
		levels++;
	}
	return levels;
}

/**
 * Construct the path of the block file holding a given position of a
 * treefiles export, appending it to the export root already in name.
 *
 * @param name buffer holding the export root, which will be extended to
 * the full path of the block file
 * @param lenmax the total size of the name buffer
 * @param size the total size of the export
 * @param pos the position within the export
 * @param ppos [out] the position within the block file
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int levels = treelevels(size);
	uint64_t block = pos / TREEPAGESIZE;
	char *p = name + strlen(name);

	assert(pos >= 0 && pos < size);

	*ppos = pos % TREEPAGESIZE;
	for (int i = levels - 1; i >= 0; i--) {
		uint64_t divisor = 1;
		int n;
		for (int j = 0; j < i; j++)
			divisor *= TREEDIRSIZE;
		if (lenmax <= p - name)
			break;
		n = snprintf(p, lenmax - (p - name), "/%s%04" PRIu64,
				i ? "TREE" : "FILE",
				(block / divisor) % TREEDIRSIZE);
		if (n < 0)
			break;
		p += n;
	}
}

/**
 * Create the directory in path, along with any missing parent
 * directories. Directories that already exist are fine.
 *
 * @param path the directory to create; modified temporarily
 **/
void mkdir_path(char *path) {
	char *p;

	for (p = path + 1; *p; p++) {
		if (*p == '/') {
			*p = '\0';
			if (mkdir(path, 0700) < 0 && errno != EEXIST) {
				msg(LOG_ERR, "Could not create directory %s (%s)",
						path, strerror(errno));
			}
			*p = '/';
		}
	}
	if (mkdir(path, 0700) < 0 && errno != EEXIST) {
		msg(LOG_ERR, "Could not create directory %s (%s)",
				path, strerror(errno));
	}
}

/**
 * Open the block file holding a given position of a treefiles export.
 *
 * If mode includes O_CREAT, any missing directories and the block file
 * itself are created. The mutex serialises such creation, which not all
 * of the filesystems this feature is intended for cope with otherwise.
 *
 * @param name the root of the export tree (a directory)
 * @param mode the mode to open the file with, as for open(2)
 * @param size the total size of the export
 * @param pos the position within the export
 * @param mutex mutex to serialise file and directory creation
 * @return a file descriptor for the block file, or -1 on error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	size_t len = strlen(name) + TREEPATH_EXTRA;
	char *path;
	char *sep;
	off_t ppos;
	int fd;

	path = malloc(len);
	if (!path) {
		errno = ENOMEM;
		return -1;
	}
	strcpy(path, name);
	construct_path(path, (int)len, size, pos, &ppos);

	if (mode & O_CREAT) {
		pthread_mutex_lock(mutex);
		sep = strrchr(path, '/');
		if (sep != NULL) {
			*sep = '\0';
			mkdir_path(path);
			*sep = '/';
		}
		fd = open(path, mode, 0600);
		pthread_mutex_unlock(mutex);
	} else {
		fd = open(path, mode);
	}
	DEBUG("(TREEFILE %s fd %d), ", path, fd);
	free(path);
	return fd;
}

/**
 * Delete the block file holding a given position of a treefiles export,
 * if it exists.
 *
 * @param name the root of the export tree (a directory)
 * @param size the total size of the export
 * @param pos the position within the export
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	size_t len = strlen(name) + TREEPATH_EXTRA;
	char *path;
	off_t ppos;

	path = malloc(len);
	if (!path)
		return;
	strcpy(path, name);
	construct_path(path, (int)len, size, pos, &ppos);
	if (unlink(path) < 0 && errno != ENOENT) {
		msg(LOG_ERR, "Could not delete treefile %s (%s)",
				path, strerror(errno));
	}
	free(path);
}

