ssize_t rawexptreefile_read(off_t a, char *buf, size_t len, CLIENT *client) {
	ssize_t retval;
	int fhandle;

	if (len > (size_t)(TREEPAGESIZE - a % TREEPAGESIZE))
		len = TREEPAGESIZE - a % TREEPAGESIZE;

	fhandle = open_treefile(client->exportname, O_RDONLY,
			client->exportsize, a, &client->lock);
	if (fhandle < 0) {
		if (errno == ENOENT) {
			/* the block was never written, read back zeroes */
			memset(buf, 0, len);
			return len;
		}
		return -1;
	}
	DEBUG("(READ from treefile offset %llu len %u), ", (unsigned long long)(a % TREEPAGESIZE), (unsigned int)len);
	retval = pread(fhandle, buf, len, a % TREEPAGESIZE);
	if (retval >= 0 && (size_t)retval < len) {
		/* the block file is shorter than it should be; treat the
		 * missing bytes as zeroes */
		memset(buf + retval, 0, len - retval);
		retval = len;
	}
	close(fhandle);
	return retval;
}

