/*
 * Tree files support
 *
 * A treefiles export stores its data in a tree of small fixed-size block
 * files below the directory named by the exportname, rather than in a
 * single (potentially very large) file. This is useful to provide a
 * virtual block device on an underlying filesystem that does not handle
 * large files well, for example fuse/ftpfs, davfs or other network
 * filesystems.
 *
 * The individual block files are TREEPAGESIZE bytes each, and every
 * directory holds at most TREEDIRSIZE files or subdirectories. The
 * nesting level of subdirectories required to address all blocks of the
 * export is derived from the export size. Subdirectories are named
 * TREEXXXX, block files FILEXXXX, where XXXX is the zero-padded index
 * of the entry within its parent directory.
 */

#include <nbdsrv.h>

#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>

#include <sys/stat.h>
#include <sys/types.h>

#include "treefiles.h"
#include "nbd-debug.h"

/* Extra space needed on top of the length of the exportname to store a
 * full block file path: with 64 bit file offsets, an export can span at
 * most 6 levels of TREEDIRSIZE entries ("/TREEXXXX" each, plus the
 * "FILEXXXX" leaf and the trailing NUL). */
#define TREEPATH_EXTRA 64

/**
 * Compute the number of digits needed to address all blocks of an export
 * of the given size in base TREEDIRSIZE. One of the digits is used for
 * the block file name itself, the remaining ones for subdirectories.
 **/
static int treelevels(off_t size) {
	uint64_t blocks = ((uint64_t)size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	uint64_t capacity = TREEDIRSIZE;
	int levels = 1;

	while (capacity < blocks) {
		capacity *= TREEDIRSIZE;
		levels++;
	}
	return levels;
}

